<?php
defined('ABSPATH')||exit;

final class TAB_Product_Flow {
	public static function start($user,$chat,$lang,$mode='new'){
		if(!class_exists('WC_Product')){self::say($chat,$lang,'wc_missing');return;}
		if('edit'===$mode){self::save($user->ID,array('type'=>'product','mode'=>'edit','step'=>'lookup','data'=>array()));self::say($chat,$lang,'lookup',self::controls($lang,false,false));return;}
		self::save($user->ID,array('type'=>'product','mode'=>'new','step'=>'type','data'=>array()));self::prompt($chat,$lang,'type');
	}
	public static function message($user,$chat,$message,$lang,$flow){
		$text=isset($message['text'])?trim(sanitize_text_field($message['text'])):'';$s=$flow['step'];$d=$flow['data'];
		if(in_array($s,array('image','edit_image'),true)){if(!empty($message['photo'])){$photos=$message['photo'];$d['image_file_id']=sanitize_text_field(end($photos)['file_id']);if('edit_image'===$s){$flow['data']=$d;$flow['step']='edit_menu';self::save($user->ID,$flow);self::edit_menu($chat,$lang,$flow);}else self::advance($user,$chat,$lang,$flow,$d,'category');return;}self::say($chat,$lang,'image_invalid',self::controls($lang,true,true));return;}
		if(!$text)return;
		if('lookup'===$s){$product=self::find_product($text);if(!$product){self::say($chat,$lang,'not_found',self::controls($lang,false,false));return;}$d=self::from_product($product);$flow['data']=$d;$flow['product_id']=$product->get_id();$flow['step']='edit_menu';self::save($user->ID,$flow);self::edit_menu($chat,$lang,$flow);return;}
		if('name'===$s){if(mb_strlen($text)<2){self::say($chat,$lang,'bad_name');return;}$d['name']=sanitize_text_field($text);self::advance($user,$chat,$lang,$flow,$d,'image');return;}
		if('price'===$s){$v=self::number($text);if($v<1){self::say($chat,$lang,'bad_price');return;}$d['price']=$v;self::advance($user,$chat,$lang,$flow,$d,'sale');return;}
		if('sale'===$s){$v=self::number($text);if($v<1||$v>=$d['price']){self::say($chat,$lang,'bad_sale');return;}$d['sale']=$v;self::advance($user,$chat,$lang,$flow,$d,'weight');return;}
		if('weight'===$s){if(!is_numeric(str_replace(',','.',$text))){self::say($chat,$lang,'bad_number');return;}$d['weight']=wc_format_decimal(str_replace(',','.',$text));self::advance($user,$chat,$lang,$flow,$d,'dimensions');return;}
		if('dimensions'===$s){if(!preg_match('/^\s*([0-9.,]+)\s*[x×*]\s*([0-9.,]+)\s*[x×*]\s*([0-9.,]+)\s*$/u',$text,$m)){self::say($chat,$lang,'bad_dimensions');return;}$d['length']=wc_format_decimal(str_replace(',','.',$m[1]));$d['width']=wc_format_decimal(str_replace(',','.',$m[2]));$d['height']=wc_format_decimal(str_replace(',','.',$m[3]));self::advance($user,$chat,$lang,$flow,$d,'stock_status');return;}
		if('quantity'===$s){$d['quantity']=self::number($text);self::advance($user,$chat,$lang,$flow,$d,'sku');return;}
		if('sku'===$s){$sku=wc_clean($text);$found=wc_get_product_id_by_sku($sku);if($found&&absint($found)!==absint($flow['product_id']??0)){self::say($chat,$lang,'duplicate_sku');return;}$d['sku']=$sku;self::advance($user,$chat,$lang,$flow,$d,'description');return;}
		if('description'===$s){$d['description']=sanitize_textarea_field($text);self::advance($user,$chat,$lang,$flow,$d,'attributes');return;}
		if('attributes'===$s){if(empty($d['type'])||'variable'!==$d['type']){$d['attribute_name']='';$d['attribute_values']=array();self::review($user,$chat,$lang,$flow,$d);return;}if(false===strpos($text,':')){self::say($chat,$lang,'bad_attributes');return;}list($name,$values)=array_map('trim',explode(':',$text,2));$values=array_values(array_filter(array_map('sanitize_text_field',explode(',',$values))));if(!$name||count($values)<2){self::say($chat,$lang,'bad_attributes');return;}$d['attribute_name']=sanitize_text_field($name);$d['attribute_values']=$values;self::review($user,$chat,$lang,$flow,$d);return;}
		if(0===strpos($s,'edit_')){self::edit_value($user,$chat,$lang,$flow,$text);return;}
	}
	public static function callback($user,$chat,$lang,$flow,$action,$message_id){
		if('menu'===$action){delete_user_meta($user->ID,'tab_flow');TAB_Telegram::send($chat,'fa'===$lang?'بازگشت به منوی اصلی':'Back to main menu',TAB_Telegram::menu($lang));return;}
		if('cancel'===$action){delete_user_meta($user->ID,'tab_flow');self::say($chat,$lang,'cancelled',TAB_Telegram::menu($lang));return;}
		if('back'===$action){if('edit'===($flow['mode']??'')&&0===strpos($flow['step'],'edit_')){$flow['step']='edit_menu';self::save($user->ID,$flow);self::edit_menu($chat,$lang,$flow);}else self::back($user,$chat,$lang,$flow);return;}
		if('skip'===$action){self::skip_step($user,$chat,$lang,$flow);return;}
		if(0===strpos($action,'type_')){$flow['data']['type']=substr($action,5);$flow['step']='name';self::save($user->ID,$flow);self::prompt($chat,$lang,'name');return;}
		if(0===strpos($action,'cat_')){$flow['data']['category_id']=absint(substr($action,4));self::advance($user,$chat,$lang,$flow,$flow['data'],'price');return;}
		if(0===strpos($action,'stock_')){$flow['data']['stock_status']=sanitize_key(substr($action,6));$next='instock'===$flow['data']['stock_status']?'quantity':'sku';self::advance($user,$chat,$lang,$flow,$flow['data'],$next);return;}
		if('confirm'===$action){self::create_or_update($user,$chat,$lang,$flow);return;}
		if(0===strpos($action,'editfield_')){$field=sanitize_key(substr($action,10));$flow['step']='edit_'.$field;self::save($user->ID,$flow);if('image'===$field)TAB_Telegram::send($chat,'fa'===$lang?'تصویر جدید را ارسال کنید.':'Send the new image.',self::controls($lang,true,false));else self::say($chat,$lang,'edit_'.$field,self::controls($lang,true,false));return;}
		if('edit_done'===$action){self::create_or_update($user,$chat,$lang,$flow);return;}
	}
	private static function prompt($chat,$lang,$step){
		if('type'===$step){$kb=TAB_Telegram::inline(array(array(array('text'=>self::t($lang,'simple'),'callback_data'=>'pf:type_simple'),array('text'=>self::t($lang,'variable'),'callback_data'=>'pf:type_variable')),array(array('text'=>self::t($lang,'cancel'),'callback_data'=>'pf:cancel'))));self::say($chat,$lang,'type',$kb);return;}
		if('category'===$step){$rows=array();foreach(get_terms(array('taxonomy'=>'product_cat','hide_empty'=>false,'number'=>20))as$term){if(is_wp_error($term))break;$rows[]=array(array('text'=>$term->name,'callback_data'=>'pf:cat_'.$term->term_id));}$rows[]=array(array('text'=>self::t($lang,'skip'),'callback_data'=>'pf:skip'),array('text'=>self::t($lang,'back'),'callback_data'=>'pf:back'),array('text'=>self::t($lang,'cancel'),'callback_data'=>'pf:cancel'));self::say($chat,$lang,'category',TAB_Telegram::inline($rows));return;}
		if('stock_status'===$step){$kb=TAB_Telegram::inline(array(array(array('text'=>self::t($lang,'instock'),'callback_data'=>'pf:stock_instock'),array('text'=>self::t($lang,'outofstock'),'callback_data'=>'pf:stock_outofstock')),array(array('text'=>self::t($lang,'backorder'),'callback_data'=>'pf:stock_onbackorder')),array(array('text'=>self::t($lang,'back'),'callback_data'=>'pf:back'),array('text'=>self::t($lang,'cancel'),'callback_data'=>'pf:cancel'))));self::say($chat,$lang,'stock_status',$kb);return;}
		self::say($chat,$lang,$step,self::controls($lang,true,in_array($step,array('image','sale','weight','dimensions','quantity','sku','description','attributes'),true)));
	}
	private static function advance($user,$chat,$lang,$flow,$data,$step){$flow['data']=$data;$flow['step']=$step;self::save($user->ID,$flow);self::prompt($chat,$lang,$step);}
	private static function review($user,$chat,$lang,$flow,$d){$flow['data']=$d;$flow['step']='confirm';self::save($user->ID,$flow);$text=self::t($lang,'review')."\n\n".$d['name']."\n".self::t($lang,'type_label').': '.self::t($lang,$d['type'])."\n".self::t($lang,'price_label').': '.number_format($d['price'])."\n".self::t($lang,'stock_label').': '.self::t($lang,$d['stock_status']);$kb=TAB_Telegram::inline(array(array(array('text'=>self::t($lang,'confirm'),'callback_data'=>'pf:confirm')),array(array('text'=>self::t($lang,'back'),'callback_data'=>'pf:back'),array('text'=>self::t($lang,'cancel'),'callback_data'=>'pf:cancel'))));TAB_Telegram::send($chat,$text,$kb);}
	private static function create_or_update($user,$chat,$lang,$flow){$d=$flow['data'];$editing=!empty($flow['product_id']);$p=$editing?wc_get_product($flow['product_id']):('variable'===$d['type']?new WC_Product_Variable():new WC_Product_Simple());if(!$p){self::say($chat,$lang,'not_found');return;}$p->set_name($d['name']);$p->set_regular_price(wc_format_decimal($d['price']));$p->set_sale_price(empty($d['sale'])?'':wc_format_decimal($d['sale']));$p->set_weight($d['weight']??'');$p->set_length($d['length']??'');$p->set_width($d['width']??'');$p->set_height($d['height']??'');$p->set_stock_status($d['stock_status']??'instock');if(isset($d['quantity'])&&''!==$d['quantity']){$p->set_manage_stock(true);$p->set_stock_quantity(absint($d['quantity']));}if(!empty($d['sku']))$p->set_sku($d['sku']);$p->set_description($d['description']??'');if(!empty($d['category_id']))$p->set_category_ids(array(absint($d['category_id'])));$p->set_status($editing?$p->get_status():'draft');$id=$p->save();if(!empty($d['image_file_id'])){$image=self::import_image($d['image_file_id'],$id);if(!is_wp_error($image)){$p->set_image_id($image);$p->save();}}if('variable'===$d['type']&&!empty($d['attribute_values']))self::variations($p,$d);delete_user_meta($user->ID,'tab_flow');$url=get_edit_post_link($id,'');$kb=TAB_Telegram::inline(array(array(array('text'=>self::t($lang,'open'),'url'=>$url))));TAB_Telegram::send($chat,sprintf(self::t($lang,$editing?'updated':'created'),$id),$kb);}
	private static function variations($p,$d){$a=new WC_Product_Attribute();$a->set_id(0);$a->set_name($d['attribute_name']);$a->set_options($d['attribute_values']);$a->set_visible(true);$a->set_variation(true);$p->set_attributes(array($a));$p->save();foreach($d['attribute_values']as$value){$v=new WC_Product_Variation();$v->set_parent_id($p->get_id());$v->set_attributes(array(sanitize_title($d['attribute_name'])=>$value));$v->set_regular_price(wc_format_decimal($d['price']));if(!empty($d['sale']))$v->set_sale_price(wc_format_decimal($d['sale']));$v->set_status('publish');$v->save();}}
	private static function import_image($file_id,$post_id){$url=TAB_Telegram::file_url($file_id);if(is_wp_error($url))return $url;require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/image.php';$tmp=download_url($url,30);if(is_wp_error($tmp))return $tmp;$file=array('name'=>'telegram-product-'.time().'.jpg','tmp_name'=>$tmp);$id=media_handle_sideload($file,$post_id);if(is_wp_error($id))@unlink($tmp);return $id;}
	private static function find_product($q){if(ctype_digit($q))return wc_get_product(absint($q));$id=wc_get_product_id_by_sku(wc_clean($q));return $id?wc_get_product($id):false;}
	private static function from_product($p){return array('type'=>$p->is_type('variable')?'variable':'simple','name'=>$p->get_name(),'price'=>$p->get_regular_price(),'sale'=>$p->get_sale_price(),'weight'=>$p->get_weight(),'length'=>$p->get_length(),'width'=>$p->get_width(),'height'=>$p->get_height(),'stock_status'=>$p->get_stock_status(),'quantity'=>$p->get_stock_quantity(),'sku'=>$p->get_sku(),'description'=>$p->get_description(),'category_id'=>current($p->get_category_ids())?:0);}
	private static function edit_menu($chat,$lang,$flow){$d=$flow['data'];$image='fa'===$lang?'ویرایش تصویر':'Edit image';$rows=array(array(array('text'=>self::t($lang,'edit_name'),'callback_data'=>'pf:editfield_name'),array('text'=>self::t($lang,'edit_price'),'callback_data'=>'pf:editfield_price')),array(array('text'=>self::t($lang,'edit_stock'),'callback_data'=>'pf:editfield_stock'),array('text'=>$image,'callback_data'=>'pf:editfield_image')),array(array('text'=>self::t($lang,'save_changes'),'callback_data'=>'pf:edit_done')),array(array('text'=>self::t($lang,'cancel'),'callback_data'=>'pf:cancel')));TAB_Telegram::send($chat,$d['name'].' (#'.$flow['product_id'].')',TAB_Telegram::inline($rows));}
	private static function edit_value($user,$chat,$lang,$flow,$text){$field=substr($flow['step'],5);$d=$flow['data'];if('name'===$field)$d['name']=sanitize_text_field($text);elseif('price'===$field){$v=self::number($text);if(!$v){self::say($chat,$lang,'bad_price');return;}$d['price']=$v;}elseif('stock'===$field){$d['quantity']=self::number($text);$d['stock_status']='instock';}elseif('image'===$field){self::say($chat,$lang,'image_invalid');return;}$flow['data']=$d;$flow['step']='edit_menu';self::save($user->ID,$flow);self::edit_menu($chat,$lang,$flow);}
	private static function skip_step($user,$chat,$lang,$f){$map=array('image'=>'category','category'=>'price','sale'=>'weight','weight'=>'dimensions','dimensions'=>'stock_status','quantity'=>'sku','sku'=>'description','description'=>'attributes','attributes'=>'confirm');$s=$f['step'];if('attributes'===$s){$f['data']['attribute_name']='';$f['data']['attribute_values']=array();self::review($user,$chat,$lang,$f,$f['data']);return;}if(isset($map[$s]))self::advance($user,$chat,$lang,$f,$f['data'],$map[$s]);}
	private static function back($user,$chat,$lang,$f){$map=array('name'=>'type','image'=>'name','category'=>'image','price'=>'category','sale'=>'price','weight'=>'sale','dimensions'=>'weight','stock_status'=>'dimensions','quantity'=>'stock_status','sku'=>'quantity','description'=>'sku','attributes'=>'description','confirm'=>'attributes');$f['step']=$map[$f['step']]??$f['step'];self::save($user->ID,$f);self::prompt($chat,$lang,$f['step']);}
	private static function controls($l,$back=true,$skip=false){$row=array();if($skip)$row[]=array('text'=>self::t($l,'skip'),'callback_data'=>'pf:skip');if($back)$row[]=array('text'=>self::t($l,'back'),'callback_data'=>'pf:back');$row[]=array('text'=>self::t($l,'cancel'),'callback_data'=>'pf:cancel');$menu='fa'===$l?'بازگشت به منو':'Back to menu';return TAB_Telegram::inline(array($row,array(array('text'=>$menu,'callback_data'=>'pf:menu'))));}
	private static function save($id,$f){$f['updated']=time();update_user_meta($id,'tab_flow',$f);}
	private static function number($v){$v=strtr($v,array('۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9','٬'=>'',','=>''));return absint(preg_replace('/[^0-9]/','',$v));}
	private static function say($c,$l,$k,$kb=null){TAB_Telegram::send($c,self::t($l,$k),$kb);}
	private static function t($l,$k){$x=array('wc_missing'=>array('ووکامرس فعال نیست.','WooCommerce is not active.'),'lookup'=>array('شناسه محصول یا SKU را ارسال کنید.','Send a product ID or SKU.'),'not_found'=>array('محصول پیدا نشد.','Product not found.'),'type'=>array('نوع محصول را انتخاب کنید.','Choose the product type.'),'simple'=>array('ساده','Simple'),'variable'=>array('متغیر','Variable'),'name'=>array('نام محصول را ارسال کنید.','Send the product name.'),'image'=>array('تصویر محصول را ارسال کنید.','Send the product image.'),'image_invalid'=>array('لطفاً تصویر را به‌صورت Photo ارسال کنید.','Please send an image as a Photo.'),'category'=>array('دسته‌بندی را انتخاب کنید.','Choose a category.'),'price'=>array('قیمت اصلی را وارد کنید.','Enter the regular price.'),'sale'=>array('قیمت ویژه را وارد کنید.','Enter the sale price.'),'weight'=>array('وزن محصول را وارد کنید.','Enter product weight.'),'dimensions'=>array('ابعاد را به شکل طول×عرض×ارتفاع وارد کنید.','Enter dimensions as length×width×height.'),'stock_status'=>array('وضعیت موجودی را انتخاب کنید.','Choose stock status.'),'quantity'=>array('تعداد موجودی را وارد کنید.','Enter stock quantity.'),'sku'=>array('SKU را وارد کنید.','Enter the SKU.'),'description'=>array('توضیحات محصول را ارسال کنید.','Send the product description.'),'attributes'=>array('ویژگی محصول متغیر را مانند رنگ: قرمز, آبی وارد کنید.','Enter a variable attribute like Color: Red, Blue.'),'review'=>array('اطلاعات محصول را بررسی کنید:','Review the product:'),'confirm'=>array('تأیید نهایی','Final confirmation'),'cancel'=>array('لغو','Cancel'),'back'=>array('مرحله قبل','Previous step'),'skip'=>array('ردکردن','Skip'),'instock'=>array('موجود','In stock'),'outofstock'=>array('ناموجود','Out of stock'),'backorder'=>array('پیش‌خرید','On backorder'),'cancelled'=>array('فرایند لغو شد.','Process cancelled.'),'bad_name'=>array('نام معتبر وارد کنید.','Enter a valid name.'),'bad_price'=>array('قیمت معتبر وارد کنید.','Enter a valid price.'),'bad_sale'=>array('قیمت ویژه باید کمتر از قیمت اصلی باشد.','Sale price must be lower than regular price.'),'bad_number'=>array('عدد معتبر وارد کنید.','Enter a valid number.'),'bad_dimensions'=>array('قالب ابعاد صحیح نیست.','Invalid dimensions format.'),'bad_attributes'=>array('حداقل دو مقدار ویژگی وارد کنید.','Enter at least two attribute values.'),'duplicate_sku'=>array('این SKU قبلاً استفاده شده است.','This SKU is already used.'),'type_label'=>array('نوع','Type'),'price_label'=>array('قیمت','Price'),'stock_label'=>array('موجودی','Stock'),'open'=>array('بازکردن محصول در سایت','Open product in site'),'created'=>array('محصول #%d ساخته شد.','Product #%d was created.'),'updated'=>array('محصول #%d ویرایش شد.','Product #%d was updated.'),'edit_name'=>array('ویرایش نام','Edit name'),'edit_price'=>array('ویرایش قیمت','Edit price'),'edit_stock'=>array('ویرایش موجودی','Edit stock'),'edit_image'=>array('ویرایش تصویر','Edit image'),'save_changes'=>array('ذخیره تغییرات','Save changes'),'edit_image'=>array('تصویر جدید را ارسال کنید.','Send the new image.'));return $x[$k]['fa'===$l?0:1]??$k;}
}
